UPDATE student
SET last_response_at = CASE
    WHEN last_response_at IS NULL OR last_response_at < #{respondedAt}
        THEN #{respondedAt}
    ELSE last_response_at
END
WHERE id = #{studentId}

mapper.select:
SELECT h.id AS help_request_id, h.student_id, h.recommendation_item_id, h.help_type, h.contact_method, h.memo, h.status, h.created_at, h.closed_at, h.close_reason, h.consultation_at, j.title AS job_title FROM help_request h LEFT JOIN recommendation_item ri ON ri.id = h.recommendation_item_id LEFT JOIN job_posting j ON j.id = ri.job_posting_id WHERE h.student_id = #{studentId}
AND h.status = #{status}
ORDER BY h.created_at DESC, h.id DESC

mapper.update:
UPDATE help_request
SET contact_method = #{contactMethod,jdbcType=VARCHAR}, memo = #{memo,jdbcType=LONGVARCHAR}
WHERE id = #{helpRequestId}

UPDATE help_request
SET status = #{status}, consultation_at = #{consultationAt,jdbcType=TIMESTAMP}
WHERE id = #{helpRequestId}

UPDATE help_request
SET status = 'CLOSED', closed_at = #{closedAt}, close_reason = #{closeReason}
WHERE id = #{helpRequestId} AND status IN ('OPEN', 'IN_PROGRESS', 'CONSULTATION_SCHEDULED')
